<?php declare(strict_types=1);namespace App\Modules\Subcontracts\Validators;use App\Core\Exceptions\ValidationException;use App\Core\Validation\Validator;use App\Modules\Subcontracts\DTOs\SubcontractData;final class SubcontractValidator{public function __construct(private readonly Validator$v){}public function validate(array$i):SubcontractData{if(!$this->v->validate($i,['project_id'=>'required','work_section_id'=>'required','vendor_id'=>'required','pricing_method'=>'required','title'=>'required|string|max:190','subcontract_number'=>'string|max:100','description'=>'string|max:5000','contract_date'=>'required','notes'=>'string|max:5000']))throw new ValidationException($this->v->errors());$e=[];$p=$this->id($i['project_id']??null);$s=$this->id($i['work_section_id']??null);$v=$this->id($i['vendor_id']??null);$m=(string)($i['pricing_method']??'boq');if(!$p)$e['project_id'][]='المشروع غير صالح.';if(!$s)$e['work_section_id'][]='مجال العمل مطلوب.';if(!$v)$e['vendor_id'][]='المقاول غير صالح.';if(!in_array($m,['boq','lump_sum'],true))$e['pricing_method'][]='طريقة التسعير غير صالحة.';$cd=$this->date($i['contract_date']??null);$sd=$this->date($i['start_date']??null);$ed=$this->date($i['expected_end_date']??null);if(!$cd)$e['contract_date'][]='التاريخ غير صالح.';if($sd&&$ed&&$ed<$sd)$e['expected_end_date'][]='تاريخ الانتهاء يسبق البدء.';$value=$this->dec($i['contract_value']??null);if($e)throw new ValidationException($e);return new SubcontractData((int)$p,(int)$s,(int)$v,'boq',$this->n($i['subcontract_number']??null),trim((string)$i['title']),$this->n($i['description']??null),(string)$cd,$sd,$ed,$value,$this->n($i['notes']??null));}private function id(mixed$x):?int{$v=filter_var($x,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);return$v===false?null:$v;}private function n(mixed$x):?string{$x=trim((string)$x);return$x===''?null:$x;}private function date(mixed$x):?string{$x=trim((string)$x);if($x==='')return null;$d=\DateTimeImmutable::createFromFormat('!Y-m-d',$x);return$d&&$d->format('Y-m-d')===$x?$x:null;}private function dec(mixed$x):?string{$x=trim((string)$x);return$x!==''&&preg_match('/^\d+(?:\.\d+)?$/',$x)?number_format((float)$x,2,'.',''):null;}}
